import { NextResponse } from "next/server";
import { requireStorefrontAdmin } from "@/lib/adminRouteAuth";

const ORIGINS = ["storefront", "web_app", "mobile_app", "admin"] as const;

export async function GET() {
  const gate = await requireStorefrontAdmin();
  if (!gate.ok) return gate.response;

  const svc = gate.svc;
  const since7 = new Date(Date.now() - 7 * 864e5).toISOString();

  try {
    const [
      platformStatsRes,
      waitlistRes,
      profilesTotal,
      sellers,
      buyerProfiles,
      productsActive,
      guestUnclaimed,
      payoutFailed,
      payoutQueued,
      storefrontPaidSettlement,
      ordersWeb7d,
      ordersMobile7d,
      recentSignupsRes,
      recentWebOrdersRes,
      ...originCounts
    ] = await Promise.all([
      svc.rpc("get_platform_stats"),
      svc.from("waitlist").select("*", { count: "exact", head: true }),
      svc.from("profiles").select("*", { count: "exact", head: true }),
      svc.from("profiles").select("*", { count: "exact", head: true }).eq("is_seller", true),
      svc.from("profiles").select("*", { count: "exact", head: true }).or("is_seller.eq.false,is_seller.is.null"),
      svc.from("storefront_products").select("*", { count: "exact", head: true }).eq("is_active", true),
      svc.from("orders").select("*", { count: "exact", head: true }).eq("is_guest_checkout", true).is("claimed_by_user_id", null),
      svc.from("orders").select("*", { count: "exact", head: true }).eq("payout_status", "failed"),
      svc
        .from("orders")
        .select("*", { count: "exact", head: true })
        .eq("status", "COMPLETED")
        .in("payout_status", ["pending", "retry_queued"]),
      svc
        .from("orders")
        .select("*", { count: "exact", head: true })
        .eq("origin_channel", "storefront")
        .eq("status", "PAID")
        .not("payment_reference", "is", null),
      svc
        .from("orders")
        .select("*", { count: "exact", head: true })
        .in("origin_channel", ["storefront", "web_app"])
        .gte("created_at", since7),
      svc.from("orders").select("*", { count: "exact", head: true }).eq("origin_channel", "mobile_app").gte("created_at", since7),
      svc
        .from("profiles")
        .select("id, email, full_name, display_name, is_seller, acquisition_channel, created_at")
        .order("created_at", { ascending: false })
        .limit(10),
      svc
        .from("orders")
        .select(
          "id, status, total_amount, currency_code, origin_channel, checkout_mode, is_guest_checkout, guest_name, guest_email, created_at, user_id, seller_id",
        )
        .in("origin_channel", ["storefront", "web_app"])
        .order("created_at", { ascending: false })
        .limit(12),
      ...ORIGINS.map((o) => svc.from("orders").select("*", { count: "exact", head: true }).eq("origin_channel", o)),
    ]);

    const ordersByOrigin: Record<string, number> = {};
    ORIGINS.forEach((o, i) => {
      ordersByOrigin[o] = originCounts[i]?.count ?? 0;
    });

    const platformStats = platformStatsRes.error ? null : platformStatsRes.data;

    return NextResponse.json({
      platformStats,
      platformStatsError: platformStatsRes.error?.message ?? null,
      waitlistCount: waitlistRes.count ?? 0,
      payoutSummary: {
        failed: payoutFailed.count ?? 0,
        payoutQueued: payoutQueued.count ?? 0,
        storefrontPaidSettlement: storefrontPaidSettlement.count ?? 0,
      },
      people: {
        totalProfiles: profilesTotal.count ?? 0,
        sellers: sellers.count ?? 0,
        buyerProfiles: buyerProfiles.count ?? 0,
      },
      catalog: {
        activeStorefrontProducts: productsActive.count ?? 0,
      },
      orders: {
        byOrigin: ordersByOrigin,
        last7d: {
          web: ordersWeb7d.count ?? 0,
          mobile: ordersMobile7d.count ?? 0,
        },
      },
      guests: {
        unclaimedCheckouts: guestUnclaimed.count ?? 0,
      },
      recentSignups: recentSignupsRes.data ?? [],
      recentWebOrders: recentWebOrdersRes.data ?? [],
    });
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : "Snapshot failed";
    return NextResponse.json({ error: msg }, { status: 500 });
  }
}
